window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8d12b00490f67c5a"]={"versions": [{"id": "FIG-8d12b00490f67c5a", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / AUTOSAR ECU-Configuration-Metamodell-Ausschnitt (ECUC Parameter Definition).\n</li><li><strong>Kontext &amp; Zweck:</strong> Spezifiziert die Konfigurationsstruktur des BSW-Moduls <code>ISO15118Chrg</code> (AUTOSAR Classic Platform, Release R24-11, Kapitel 10 <em>Configuration specification</em>). Das Diagramm definiert den strukturellen Rahmen zur Parametrierung der V2G-Nachrichten-Timeouts (Vehicle-to-Grid) für den EVCC-Kommunikationscontroller (Electric Vehicle Communication Controller) nach ISO 15118-2/-20.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten (Metaklassen-Instanzen des AUTOSAR ECUC Metamodells):</strong>\n<ul class=\"fig-list\"><li><code>ISO15118ChrgTimer</code> (<code>: EcucParamConfContainerDef</code>):\n<ul class=\"fig-list\"><li>Konfigurations-Container zur Bündelung von Timer-Parametern.\n</li><li>Multiplizität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code> (Container ist optional und kann mehrfach instanziiert werden).\n</li></ul>\n</li><li><code>ISO15118ChrgV2gEvccMsgTimeout</code> (<code>: EcucFloatParamDef</code>):\n<ul class=\"fig-list\"><li>Fließkomma-Konfigurationsparameter (Einheit: Sekunden) zur Festlegung des maximalen Timeout-Intervalls für empfangene V2G-Nachrichten.\n</li></ul>\n</li></ul>\n</li><li><strong>Beziehungen:</strong>\n<ul class=\"fig-list\"><li><strong>Komposition</strong> (<code>+parameter</code>): <code>ISO15118ChrgTimer</code> aggregiert existenziell den Parameter <code>ISO15118ChrgV2gEvccMsgTimeout</code>. Der Parameter existiert ausschließlich im Lebenszyklus des übergeordneten Containers.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Laufzeitsemantik (Timer-Überwachung):</strong>\n<ol class=\"fig-list\"><li><strong>Startbedingung:</strong> Nach dem Senden einer V2G-Anforderungsnachricht (<code>*Req</code>, z. B. <code>SessionSetupReq</code>, <code>ServiceDiscoveryReq</code>, <code>ChargeLoopReq</code>) startet der EVCC-Zustandsautomat die Überwachungszeit basierend auf <code>ISO15118ChrgV2gEvccMsgTimeout</code>.\n</li><li><strong>Synchrone/Asynchrone Pfade:</strong> \n<ul class=\"fig-list\"><li><em>Erfolgsfall:</em> Eintreffen der korrespondierenden Antwort (<code>*Res</code>) vor Ablauf des Timers stoppt/resettet den Timer; Zustandsübergang im Kommunikationsprotokoll erfolgt regulär.\n</li><li><em>Timeout-Fall:</em> Läuft der Timer ohne Empfang der erwarteten PDU/Nachricht ab, tritt die Abbruchbedingung ein.\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong> \n<ul class=\"fig-list\"><li>Auslösen einer Retry-Sequenz (sofern protokollarisch zulässig) oder sofortiger Abbruch der V2G-Kommunikationssitzung (<code>SessionStop</code>).\n</li><li>Optionaler Fehlereintrag via DEM (<code>ISO15118CHRG_E_COMMUNICATION_TIMEOUT</code>) bzw. Meldung an den DET bei Konfigurationsdiskrepanzen zur Laufzeit.\n</li></ul>\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>SWS-Anforderung:</strong> <code>ECUC_ISO15118Chrg_00013</code> bindet die Definition des Timeout-Parameters verbindlich an das Modul-ARXML.\n</li><li><strong>BSW-Konfiguration &amp; Code-Generierung:</strong>\n<ul class=\"fig-list\"><li>Der BSW-Code-Generator wandelt den <code>EcucFloatParamDef</code>-Wert typischerweise in softwarenahe Zählerstände (Ticks) der zyklischen Hauptfunktion (<code>ISO15118Chrg_MainFunction()</code>) oder in <code>float32</code>-Konstanten um.\n</li><li>Entwickler müssen sicherstellen, dass die Task-Periodizität von <code>ISO15118Chrg_MainFunction</code> eine hinreichende Granularität zur Auflösung von <code>ISO15118ChrgV2gEvccMsgTimeout</code> besitzt (Nyquist-/Abtastrate berücksichtigen, Rundungsverluste bei Float-zu-Tick-Konvertierung minimieren).\n</li></ul>\n</li><li><strong>ISO 15118 Konformität:</strong>\n<ul class=\"fig-list\"><li>Bei <code>lowerMultiplicity = 0</code> greifen modulintern hinterlegte Default-Werte der ISO 15118 (typisch T_EVCC_Msg_Timeout = 2.0\\,s bis 5.0\\,s je nach Nachrichtentyp). Abweichende Konfigurationen müssen strikt gegen die Timing-Anforderungen der jeweiligen Charging-Norm validiert werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-5e122245bb5247d0", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / AUTOSAR ECU-Configuration-Metamodell-Ausschnitt (ECUC Parameter Definition).\n</li><li><strong>Kontext &amp; Zweck:</strong> Spezifiziert die Konfigurationsstruktur des BSW-Moduls <code>ISO15118Chrg</code> (AUTOSAR Classic Platform, Release R24-11, Kapitel 10 <em>Configuration specification</em>). Das Diagramm definiert den strukturellen Rahmen zur Parametrierung der V2G-Nachrichten-Timeouts (Vehicle-to-Grid) für den EVCC-Kommunikationscontroller (Electric Vehicle Communication Controller) nach ISO 15118-2/-20.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten (Metaklassen-Instanzen des AUTOSAR ECUC Metamodells):</strong>\n<ul class=\"fig-list\"><li><code>ISO15118ChrgTimer</code> (<code>: EcucParamConfContainerDef</code>):\n<ul class=\"fig-list\"><li>Konfigurations-Container zur Bündelung von Timer-Parametern.\n</li><li>Multiplizität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code> (Container ist optional und kann mehrfach instanziiert werden).\n</li></ul>\n</li><li><code>ISO15118ChrgV2gEvccMsgTimeout</code> (<code>: EcucFloatParamDef</code>):\n<ul class=\"fig-list\"><li>Fließkomma-Konfigurationsparameter (Einheit: Sekunden) zur Festlegung des maximalen Timeout-Intervalls für empfangene V2G-Nachrichten.\n</li></ul>\n</li></ul>\n</li><li><strong>Beziehungen:</strong>\n<ul class=\"fig-list\"><li><strong>Komposition</strong> (<code>+parameter</code>): <code>ISO15118ChrgTimer</code> aggregiert existenziell den Parameter <code>ISO15118ChrgV2gEvccMsgTimeout</code>. Der Parameter existiert ausschließlich im Lebenszyklus des übergeordneten Containers.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Laufzeitsemantik (Timer-Überwachung):</strong>\n<ol class=\"fig-list\"><li><strong>Startbedingung:</strong> Nach dem Senden einer V2G-Anforderungsnachricht (<code>*Req</code>, z. B. <code>SessionSetupReq</code>, <code>ServiceDiscoveryReq</code>, <code>ChargeLoopReq</code>) startet der EVCC-Zustandsautomat die Überwachungszeit basierend auf <code>ISO15118ChrgV2gEvccMsgTimeout</code>.\n</li><li><strong>Synchrone/Asynchrone Pfade:</strong> \n<ul class=\"fig-list\"><li><em>Erfolgsfall:</em> Eintreffen der korrespondierenden Antwort (<code>*Res</code>) vor Ablauf des Timers stoppt/resettet den Timer; Zustandsübergang im Kommunikationsprotokoll erfolgt regulär.\n</li><li><em>Timeout-Fall:</em> Läuft der Timer ohne Empfang der erwarteten PDU/Nachricht ab, tritt die Abbruchbedingung ein.\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong> \n<ul class=\"fig-list\"><li>Auslösen einer Retry-Sequenz (sofern protokollarisch zulässig) oder sofortiger Abbruch der V2G-Kommunikationssitzung (<code>SessionStop</code>).\n</li><li>Optionaler Fehlereintrag via DEM (<code>ISO15118CHRG_E_COMMUNICATION_TIMEOUT</code>) bzw. Meldung an den DET bei Konfigurationsdiskrepanzen zur Laufzeit.\n</li></ul>\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>SWS-Anforderung:</strong> <code>ECUC_ISO15118Chrg_00013</code> bindet die Definition des Timeout-Parameters verbindlich an das Modul-ARXML.\n</li><li><strong>BSW-Konfiguration &amp; Code-Generierung:</strong>\n<ul class=\"fig-list\"><li>Der BSW-Code-Generator wandelt den <code>EcucFloatParamDef</code>-Wert typischerweise in softwarenahe Zählerstände (Ticks) der zyklischen Hauptfunktion (<code>ISO15118Chrg_MainFunction()</code>) oder in <code>float32</code>-Konstanten um.\n</li><li>Entwickler müssen sicherstellen, dass die Task-Periodizität von <code>ISO15118Chrg_MainFunction</code> eine hinreichende Granularität zur Auflösung von <code>ISO15118ChrgV2gEvccMsgTimeout</code> besitzt (Nyquist-/Abtastrate berücksichtigen, Rundungsverluste bei Float-zu-Tick-Konvertierung minimieren).\n</li></ul>\n</li><li><strong>ISO 15118 Konformität:</strong>\n<ul class=\"fig-list\"><li>Bei <code>lowerMultiplicity = 0</code> greifen modulintern hinterlegte Default-Werte der ISO 15118 (typisch T_EVCC_Msg_Timeout = 2.0\\,s bis 5.0\\,s je nach Nachrichtentyp). Abweichende Konfigurationen müssen strikt gegen die Timing-Anforderungen der jeweiligen Charging-Norm validiert werden.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-8d12b00490f67c5a", "to": "FIG-5e122245bb5247d0", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
